const fs = require("fs");
const file = "/w/t.mjs";
fs.writeFileSync(file, [
  'import * as chat from "agents/chat";',
  'const viaUnset = chat.resolveChatRecoveryConfig(undefined).maxRecoveryWork;',
  'const viaEmpty = chat.resolveChatRecoveryConfig({}).maxRecoveryWork;',
  'console.log(JSON.stringify({ c: chat.DEFAULT_CHAT_RECOVERY_MAX_WORK, viaUnset, viaEmpty }));'
].join("\n"));
const { spawnSync } = require("child_process");
const r = spawnSync(process.execPath, [file], { encoding: "utf8", timeout: 60000 });
if (r.status !== 0) {
  console.error("ERROR: could not load agents/chat: " + (r.stderr || "").slice(0, 400));
  process.exit(2);
}
let v;
try { v = JSON.parse(r.stdout.trim().split("\n").pop()); } catch (e) {
  console.error("ERROR: unexpected output " + r.stdout);
  process.exit(2);
}
if (v.c === 10000 && v.viaUnset === 10000 && v.viaEmpty === 10000) {
  console.log("OK: default maxRecoveryWork is 10000");
  process.exit(0);
}
if (v.c === 1000 && v.viaUnset === 1000 && v.viaEmpty === 1000) {
  console.error("FAIL: default maxRecoveryWork is 1000, not 10000");
  process.exit(1);
}
console.error("ERROR: unexpected values " + JSON.stringify(v));
process.exit(2);

